from lib import *
S = SS('f62')
R = J('f62'); rl_ = R['real']; sa = R['syntax_attrs']
steps = [
    step("模板错误在 Flask 里的异常(TESTING=True 让它原样传出):未定义变量 → UndefinedError: 'user' is undefined,traceback 里有模板帧 undef.html:2;语法错误 → TemplateSyntaxError: Expected an expression, got 'end of statement block'(模板帧 syntax.html:4);找不到模板 → TemplateNotFound: nope.html(没有模板帧);在模板里做 None + 1 → TypeError: unsupported operand type(s) for +: 'NoneType' and 'int'(模板帧 typeerr.html:2);include 里的 1 / 0 → ZeroDivisionError,模板帧是 outer.html:2 与 inner.html:2(两层都指出来)。Jinja 把 traceback 改写成指向模板文件与行号。语法错误的异常对象自带 lineno = 4、name = syntax.html、message。", t=tl(S(1)), done=lidx(S(1), 'GET /undef', 'GET /syntax', 'TemplateSyntaxError 的属性'), mark=lidx(S(1), 'GET /missing-tpl', 'GET /typeerr', 'GET /in-include'), kv=KV([['未定义变量', 'UndefinedError + 模板行号'], ['语法错误', 'TemplateSyntaxError(lineno、name)'], ['找不到', 'TemplateNotFound'], ['include 里出错', '两层模板帧']], ['include 里出错'])),
    step("不是测试模式时,这些异常都是普通的 500:/undef、/missing-tpl、/in-include 都得到 500,正文是 @app.errorhandler(500) 返回的「自定义 500 页」;完整 traceback 在服务器日志里。用户看到的是错误页,开发者要去日志看模板文件与行号。", t=tl(S(2)), done=lidx(S(2), 'GET /undef', 'GET /missing-tpl', 'GET /in-include'), kv=KV([['任何模板异常', '500'], ['详细信息', '在日志里']], ['任何模板异常'])),
    step("Undefined 的宽容:默认渲染 [{{ nothing }}] 得到 '[]',不报错(缺失变量输出空字符串);把 app.jinja_env.undefined 换成 StrictUndefined 后同一个模板抛 UndefinedError: 'nothing' is undefined。开发环境用 StrictUndefined 可以尽早发现变量拼写错误。", t=tl(S(3)), done=lidx(S(3), '默认 Undefined 渲染'), mark=lidx(S(3), 'StrictUndefined'), kv=KV([['默认', '空字符串,不报错'], ['StrictUndefined', 'UndefinedError']], ['StrictUndefined'])),
    step(f"render_template 是渲染完再返回,stream_template 是边渲染边发送(真实 gunicorn + curl):模板在第 4 项出错。GET /render-bad → {rl_['/render-bad'][0]},curl 退出码 {rl_['/render-bad'][2]},正文只有 500 错误页;GET /stream-bad → {rl_['/stream-bad'][0]},curl 退出码 {rl_['/stream-bad'][2]}(18 = 传输提前结束),正文收到了 '<ul>\\n<li>1</li>\\n<li>2</li>\\n<li>3</li>\\n<li>4' 就断了。流式模板出错时已经发出的内容留在客户端、状态码仍是 200(状态行在渲染前已经发出),错误页没有机会显示。", t=tl(S(4)), done=lidx(S(4), 'GET /render-bad'), mark=lidx(S(4), 'GET /stream-bad', 'curl 退出码 18'), kv=KV([['render_template', '出错 → 500 错误页,没有半截内容'], ['stream_template', '200 + 半截内容 + 传输中断(curl 退出码 18)']], ['stream_template'])),
    step(f"调试模式(flask run --debug)的页面:模板错误时 debug 页面状态 500,{'含' if R['debug_page'][1] else '不含'}模板文件名 undef.html、{'含' if R['debug_page'][2] else '不含'}出错的模板源码行 {{{{ user.name.first }}}}、{'含' if R['debug_page'][3] else '不含'} UndefinedError —— 调试页会显示模板里出错的那一行源码(也因此不能在生产环境开启)。", t=tl(S(5)), done=lidx(S(5), 'debug 页面'), kv=KV([['debug 页面', '模板文件名 + 源码行 + 异常名']], ['debug 页面'])),
]
A = mkartf('f62', 62, 'Flask,Jinja2,模板异常,stream_template,真实验证,动画演示',
    '实测模板渲染异常:UndefinedError、TemplateSyntaxError(lineno、name)、TemplateNotFound、TypeError、include 里的错误都带着模板文件与行号;非测试模式都是 500;StrictUndefined;render_template 出错只有错误页,stream_template 出错会留下半截内容并中断传输(curl 退出码 18);debug 页面显示模板源码行。',
    '模板里出错时 Flask 给用户和开发者各看到什么?行号对不对?流式模板出错时客户端会收到什么?这篇逐种错误触发一遍,并用真实的 gunicorn 看流式模板出错的下场。',
    [('18', 'curl 在流式模板出错、传输被中断时的退出码'), ('2 层', 'include 里出错时 traceback 里出现的模板帧(outer.html 与 inner.html)'), ('500', '非测试模式下所有模板异常的状态码')],
    [('各种模板错误', '<p>上一篇:<a href="flask-template-lazy-objects.html">模板中的惰性对象</a>;下一篇:<a href="flask-template-cache.html">模板缓存</a>。流式响应的更多细节见<a href="flask-streaming-response.html">Streaming Response</a>。</p>'), ('生产环境的 500', None), ('Undefined 的宽容', None), ('流式模板出错', None), ('debug 页面', None)],
    steps, [ENV_F, '没有验证:Sentry 等错误监控对模板帧的显示、模板里 {% raw %} 与 {# #} 注释造成的行号偏移、i18n 提取过程的模板语法错误、stream_template 配合 stream_with_context 的更复杂情形'], '模板异常')
